def build(p):
    import cadquery as cq
    r = p['R_station'] + 120
    x = cq.Workplane("XY").box(2 * r, p['t'], p['arm_w']).union(cq.Workplane("XY").box(p['arm_w'], p['t'], 2 * r))
    hub = cq.Workplane("XZ").circle(p['arm_w'] * 0.9).extrude(p['t'] / 2, both=True)
    return x.union(hub).translate((0, p['y'], 0))
